#include <cstdio>
#include <cstddef>

// a 占 1 字节；b 是 double，必须 8 字节对齐 → a 后补 7 字节
// c 占 1 字节；结构体整体按最大成员对齐（8）→ 尾部再补 7 字节
struct S {
    char   a;
    double b;
    char   c;
};

int main() {
    printf("sizeof(S)=%zu alignof(S)=%zu\n", sizeof(S), alignof(S));
    printf("offset a=%zu b=%zu c=%zu\n",
           offsetof(S, a), offsetof(S, b), offsetof(S, c));
    // 填充字节 = 结构体总大小 - 各成员有效大小之和
    size_t raw = sizeof(char) + sizeof(double) + sizeof(char);
    printf("填充字节总数=%zu\n", sizeof(S) - raw);
    return 0;
}
